// #392 regression: a collection marker NESTED under a plain element must
// normalize to its cx-native node before the XML emitter runs. Before the
// flatten_slots recursion fix this leaked the internal marker verbatim —
// `<tags><__cx_arr__>webapi</__cx_arr__></tags>` — concatenated items, no
// per-item boundaries, unrecoverable on import.
fn test_xml_nested_array_emits_spec_carrier_not_marker() {
	out := code.eval_code('', '[tags ["web", "api"]]', 'xml') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert !out.contains('__cx_arr__'), 'internal marker leaked into XML: ${out}'
	assert out.contains('<tags><cx:arr><cx:item>web</cx:item><cx:item>api</cx:item></cx:arr></tags>'),
		'expected the conversions.md cx:arr/cx:item mapping; got: ${out}'
}

// #392: the spec'd import inverse — the cx:arr/cx:item carrier decodes back
// to an Array, so the emit→import round-trip recovers ["web", "api"] instead
// of the pre-fix concatenated "webapi".
fn test_xml_array_round_trip_recovers_items() {
	xml_out := code.eval_code('', '[tags ["web", "api"]]', 'xml') or {
		assert false, 'eval failed: ${err}'
		return
	}
	back := cx.convert_by_name(xml_out, 'xml', 'cx', false) or {
		assert false, 'xml import failed: ${err}'
		return
	}
	assert back.contains("['web', 'api']"), 'round-trip lost the array shape; got: ${back}'
}

// ── CSV / TSV: sequence-of-records → header + rows ─────────────────────────

fn test_csv_records_emit_header_and_rows() {
	doc := '[doc [order id=1 status="open"] [order id=2 status="closed"]]'
	out := code.eval_code(doc, '[?for [order \$m] [yield \$m]]', 'csv') or {
		assert false, 'eval failed: ${err}'
		return
	}
	lines := out.split('\n')
	assert lines.len == 3, 'expected 3 lines (header + 2 rows); got: ${out}'
	assert lines[0] == 'id,status', 'expected header; got: ${lines[0]}'
	assert lines[1] == '1,open', 'expected first row; got: ${lines[1]}'
	assert lines[2] == '2,closed', 'expected second row; got: ${lines[2]}'
}

fn test_tsv_records_emit_header_and_rows() {
	doc := '[doc [order id=1 status="open"] [order id=2 status="closed"]]'
	out := code.eval_code(doc, '[?for [order \$m] [yield \$m]]', 'tsv') or {
		assert false, 'eval failed: ${err}'
		return
	}
	lines := out.split('\n')
	assert lines.len == 3, 'expected 3 lines; got: ${out}'
	assert lines[0] == 'id\tstatus', 'expected tab-separated header; got: ${lines[0]}'
	assert lines[1] == '1\topen', 'got: ${lines[1]}'
}

fn test_csv_escapes_fields_with_special_chars() {
	// Field containing comma → must be quoted (RFC 4180 §2.6).
	doc := '[doc [r v="a,b"] [r v="plain"]]'
	out := code.eval_code(doc, '[?for [r \$m] [yield \$m]]', 'csv') or {
		assert false, 'eval failed: ${err}'
		return
	}
	lines := out.split('\n')
	assert lines.len == 3, 'got: ${out}'
	assert lines[1] == '"a,b"', 'expected quoted-comma field; got: ${lines[1]}'
	assert lines[2] == 'plain', 'expected unquoted plain field; got: ${lines[2]}'
}

fn test_csv_rejects_non_tabular_shape() {
	if _ := code.eval_code('', '[?let [= \$x 42] \$x]', 'csv') {
		assert false, 'scalar result should not be tabular'
		return
	} else {
		assert err.msg().contains('cx-err:CXER0100')
		assert err.msg().contains('not a sequence of records')
	}
}

fn test_csv_rejects_pure_value_sequence() {
	// A sequence of integers is not a tabular shape — no records.
	if _ := code.eval_code('', '[?let [= \$x (1, 2, 3)] \$x]', 'csv') {
		assert false, 'sequence of scalars should be rejected for csv'
		return
	} else {
		assert err.msg().contains('cx-err:CXER0100')
		assert err.msg().contains('not a sequence of records')
	}
}

// ── #438: one spelling for empty items in rendered sequences ────────────────
// The program reading preserves sequence rank (cxdm §2 MODE FORK SEQ-NEST),
// so a sequence may hold empty items. Pre-fix the multi-value/absence
// wrapper (empty [?for] result, no-branch conditional) rendered as a BARE
// HOLE between commas while literal `()` items rendered as `()` — two
// spellings of empty in one sequence, and `((), , (), ())` did not re-parse
// as CX (it fell back to the data reading as a string). Rendered program
// output MUST re-parse (bijectivity, canonical.md §1).

const seq_empty_items_src = '([?if false [then 1] [else ()]],
 [?for [in \$x ()] [yield \$x]],
 [?if true [then ()] [else 1]],
 ())'

fn test_render_seq_empty_items_one_spelling() {
	out := code.eval_code('', seq_empty_items_src, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out == '((), (), (), ())', 'every empty item renders as (); got: ${out}'
}

fn test_render_seq_empty_items_reparse_equal_value() {
	out := code.eval_code('', seq_empty_items_src, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	// The emitted text is itself a CX program whose value renders back to
	// the same text — the render fixpoint that makes the output re-parse
	// to an equal value rather than degrade to a data-fallback string.
	again := code.eval_code('', out, 'text') or {
		assert false, 're-parse of rendered output failed: ${err}'
		return
	}
	assert again == out, 'rendered output must re-parse to an equal value; got: ${again}'
	assert !again.starts_with("'"), 'output degraded to a data-fallback string: ${again}'
}

fn test_render_seq_empty_items_nested() {
	out := code.eval_code('', '(1, ([?for [in \$x ()] [yield \$x]], ()))', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out == '(1, ((), ()))', 'nested empties keep the paren spelling; got: ${out}'
	again := code.eval_code('', out, 'text') or {
		assert false, 're-parse failed: ${err}'
		return
	}
	assert again == out, 'nested render must be a re-parse fixpoint; got: ${again}'
}

fn test_render_seq_empty_single() {
	// A 1-item sequence whose item is empty. The program reading preserves
	// rank, and the literal `(())` already rendered as `(())` — the
	// computed-empty item must spell the same way (pre-fix this printed
	// `()`, which was really `(` + hole + `)`).
	out := code.eval_code('', '([?for [in \$x ()] [yield \$x]])', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out == '(())', 'single empty item spells like the (()) literal; got: ${out}'
	lit := code.eval_code('', '(())', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out == lit, 'computed and literal single-empty must agree; got ${out} vs ${lit}'
}

// ── source: vcx/tests/code_tree_test.v ──
// v0.8.0 Phase 2.11 — cx_code_tree walker tests.
//
// Verifies the V-side `cx.code_tree(source)` walker against the
// JSON contract: every node has `{kind, loc}` with
// optional `name` / `value` / `children` per the kind discriminator;
// `loc` byte offsets are valid UTF-8 substrings of `source`.
//
// Authoritative fixture-driven validation lives in
// `scripts/check_code_diagram_fixtures.py` against
// `conformance/code_diagram.txt`; this V-side test exercises the
// per-kind paths directly so module-level regressions surface
// inside `v test`.
// ── Helpers ────────────────────────────────────────────────────────────

fn parse_json(s string) json2.Any {
	v := json2.decode[json2.Any](s) or { panic('bad json: ${err.msg()} (input: ${s})') }
	return v
}

fn get_obj(v json2.Any) map[string]json2.Any {
	return v.as_map()
}

fn get_str(v json2.Any) string {
	return v.str()
}

fn get_int(v json2.Any) i64 {
	return v.int()
}

fn loc_start(n map[string]json2.Any) int {
	loc := n['loc'] or { panic('missing loc') }
	lo := loc.as_map()
	s := lo['start'] or { panic('missing loc.start') }
	return int(s.int())
}

fn loc_end(n map[string]json2.Any) int {
	loc := n['loc'] or { panic('missing loc') }
	lo := loc.as_map()
	e := lo['end'] or { panic('missing loc.end') }
	return int(e.int())
}

fn kind_of(n map[string]json2.Any) string {
	k := n['kind'] or { panic('missing kind') }
	return k.str()
}

// ── Empty / minimal ────────────────────────────────────────────────────

fn test_empty_source_returns_root_element_zero_loc() {
	out := cx.code_tree('') or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	assert n['name']!.str() == 'root'
	assert loc_start(n) == 0
	assert loc_end(n) == 0
}

fn test_whitespace_only_source() {
	out := cx.code_tree('   \n\n  ') or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	assert n['name']!.str() == 'root'
}

// ── Per-kind discriminators ────────────────────────────────────────────

fn test_bare_element() {
	source := '[user]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	assert n['name']!.str() == 'user'
	assert loc_start(n) == 0
	assert loc_end(n) == source.len
}

fn test_element_body_atom_then_int() {
	// `:id` is an atom literal (grammar.ebnf:319), NOT an attribute; `1` is a
	// separate int scalar. The walker emits per-token nodes for the diagram.
	source := '[user :id 1]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	assert n['name']!.str() == 'user'
	assert loc_end(n) == source.len
	children := n['children']!.as_array()
	assert children.len == 2, 'expected 2 body items, got ${children.len}'
	atom := children[0].as_map()
	assert kind_of(atom) == 'scalar'
	assert atom['value']!.str() == ':id'
	// `:id` spans bytes 6..9.
	assert loc_start(atom) == 6
	assert loc_end(atom) == 9
	num := children[1].as_map()
	assert kind_of(num) == 'scalar'
	assert num['value']!.int() == 1
}

fn test_element_body_atoms_and_values() {
	// `:id` / `:name` are atom scalars (not attributes); `1` is an int scalar
	// and `'alice'` a text node — four per-token body items.
	source := "[user :id 1 :name 'alice']"
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	children := n['children']!.as_array()
	assert children.len == 4, 'expected 4 body items, got ${children.len}'
	a_id := children[0].as_map()
	assert kind_of(a_id) == 'scalar'
	assert a_id['value']!.str() == ':id'
	assert children[1].as_map()['value']!.int() == 1
	a_name := children[2].as_map()
	assert kind_of(a_name) == 'scalar'
	assert a_name['value']!.str() == ':name'
	t := children[3].as_map()
	assert kind_of(t) == 'text'
	assert t['value']!.str() == 'alice'
}

fn test_element_with_text_body() {
	source := "[name 'alice']"
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	children := n['children']!.as_array()
	assert children.len == 1
	t := children[0].as_map()
	assert kind_of(t) == 'text'
	assert t['value']!.str() == 'alice'
	// 'alice' spans 6..13 (positions of the two quotes inclusive at 6 and 12; end exclusive = 13).
	assert loc_start(t) == 6
	assert loc_end(t) == 13
}

fn test_nested_elements() {
	source := '[doc [user :id 1]]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	assert n['name']!.str() == 'doc'
	children := n['children']!.as_array()
	assert children.len == 1
	inner := children[0].as_map()
	assert kind_of(inner) == 'element'
	assert inner['name']!.str() == 'user'
	inner_children := inner['children']!.as_array()
	// `:id` is an atom scalar, `1` an int scalar — two body items.
	assert inner_children.len == 2
	atom := inner_children[0].as_map()
	assert kind_of(atom) == 'scalar'
	assert atom['value']!.str() == ':id'
	assert inner_children[1].as_map()['value']!.int() == 1
}

fn test_directive_kind() {
	// Canonical clause-child surface (grammar [129] / code.md §7). Per [59]
	// the data walker treats directive children as uniform BodyItems: the
	// `[in …]` and `[yield …]` clauses surface as nested element children,
	// with no data-side clause interpretation.
	source := '[?for [in \$x /a] [yield \$x]]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'directive'
	assert n['name']!.str() == 'for'
	assert loc_start(n) == 0
	assert loc_end(n) == source.len
	children := n['children']!.as_array()
	assert children.len == 2, 'expected 2 clause children, got ${children.len}'
	c_in := children[0].as_map()
	c_yield := children[1].as_map()
	assert kind_of(c_in) == 'element'
	assert c_in['name']!.str() == 'in'
	in_kids := c_in['children']!.as_array()
	assert in_kids.len == 2
	assert in_kids[0].as_map()['value']!.str() == '\$x'
	assert kind_of(in_kids[1].as_map()) == 'path'
	assert kind_of(c_yield) == 'element'
	assert c_yield['name']!.str() == 'yield'
}

fn test_directive_colon_surface_decomposes_as_atoms() {
	// The legacy colon surface is no longer interpreted by the data walker.
	// Per [59], `:then`/`:else` round-trip as `:NAME` atom scalars (clause
	// interpretation is the program-AST layer's job, not the data side's).
	source := '[?if cond :then T :else E]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'directive'
	assert n['name']!.str() == 'if'
	children := n['children']!.as_array()
	assert children.len == 5, 'expected 5 atom/scalar children, got ${children.len}'
	assert kind_of(children[0].as_map()) == 'scalar'
	assert children[0].as_map()['value']!.str() == 'cond'
	assert kind_of(children[1].as_map()) == 'scalar'
	assert children[1].as_map()['value']!.str() == ':then'
	assert children[2].as_map()['value']!.str() == 'T'
	assert children[3].as_map()['value']!.str() == ':else'
	assert children[4].as_map()['value']!.str() == 'E'
}

fn test_directive_with_nested_element_body() {
	// Directive bodies recurse through nested clause elements. The
	// `[then …]`/`[else …]` clauses surface as element children; the
	// operator-headed condition `[> …]` has no valid element name and
	// surfaces as an anonymous `_` element (pre-existing walker trait).
	source := '[?if [> \$x 0] [then T] [else E]]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'directive'
	assert n['name']!.str() == 'if'
	children := n['children']!.as_array()
	assert children.len == 3
	assert kind_of(children[0].as_map()) == 'element'
	c_then := children[1].as_map()
	c_else := children[2].as_map()
	assert kind_of(c_then) == 'element' && c_then['name']!.str() == 'then'
	assert kind_of(c_else) == 'element' && c_else['name']!.str() == 'else'
}

// ── name=value attribute form ──────────────────────────────────────────

fn test_element_name_eq_value_int() {
	source := '[el a=1 b=2]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	assert n['name']!.str() == 'el'
	children := n['children']!.as_array()
	assert children.len == 2, 'expected 2 attributes, got ${children.len}'
	a0 := children[0].as_map()
	a1 := children[1].as_map()
	assert kind_of(a0) == 'attribute'
	assert a0['name']!.str() == 'a'
	assert a0['value']!.int() == 1
	assert kind_of(a1) == 'attribute'
	assert a1['name']!.str() == 'b'
	assert a1['value']!.int() == 2
	// loc substrings must contain the `=` form.
	a0s, a0e := loc_start(a0), loc_end(a0)
	assert source[a0s..a0e] == 'a=1'
	a1s, a1e := loc_start(a1), loc_end(a1)
	assert source[a1s..a1e] == 'b=2'
}

fn test_element_name_eq_value_string_quoted() {
	source := "[pizza size='large']"
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	children := n['children']!.as_array()
	assert children.len == 1
	attr := children[0].as_map()
	assert kind_of(attr) == 'attribute'
	assert attr['name']!.str() == 'size'
	assert attr['value']!.str() == 'large'
}

fn test_element_name_eq_value_bare_token() {
	source := '[pizza size=large]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	children := n['children']!.as_array()
	assert children.len == 1
	attr := children[0].as_map()
	assert kind_of(attr) == 'attribute'
	assert attr['name']!.str() == 'size'
	assert attr['value']!.str() == 'large'
}

fn test_element_eq_attr_then_atom() {
	// `id=1` is a real `name=value` attribute; `:name` is an atom scalar (not
	// an attribute) and `'alice'` is text — three body items.
	source := "[user id=1 :name 'alice']"
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	children := n['children']!.as_array()
	assert children.len == 3, 'expected 3 body items, got ${children.len}'
	a_eq := children[0].as_map()
	assert kind_of(a_eq) == 'attribute'
	assert a_eq['name']!.str() == 'id'
	assert a_eq['value']!.int() == 1
	a_atom := children[1].as_map()
	assert kind_of(a_atom) == 'scalar'
	assert a_atom['value']!.str() == ':name'
	t := children[2].as_map()
	assert kind_of(t) == 'text'
	assert t['value']!.str() == 'alice'
}

fn test_bare_ident_without_eq_stays_scalar() {
	// A bare identifier with no `=` must NOT be reclassified as an
	// attribute — it stays a scalar child (covers `true`, keywords,
	// bare function names, etc.).
	source := '[doc true false hello]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	children := n['children']!.as_array()
	assert children.len == 3
	for c in children {
		assert kind_of(c.as_map()) == 'scalar'
	}
	assert children[0].as_map()['value']!.bool() == true
	assert children[1].as_map()['value']!.bool() == false
	assert children[2].as_map()['value']!.str() == 'hello'
}

fn test_scalar_int_top_level() {
	source := '42'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'scalar'
	assert n['value']!.int() == 42
	assert loc_start(n) == 0
	assert loc_end(n) == 2
}

fn test_scalar_float_top_level() {
	source := '3.14'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'scalar'
	// JSON number — round-trip as float.
	assert n['value']!.f64() == 3.14
}

fn test_scalar_bool_top_level() {
	source := 'true'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'scalar'
	assert n['value']!.bool() == true
}

fn test_path_top_level_absolute() {
	source := '/users/user'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'path'
	assert n['value']!.str() == '/users/user'
	assert loc_start(n) == 0
	assert loc_end(n) == source.len
}

fn test_path_top_level_descendant() {
	source := '//user[@active]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'path'
	assert n['value']!.str().starts_with('//user')
}

// ── Loc invariants ─────────────────────────────────────────────────────

fn validate_loc_recursive(n map[string]json2.Any, source string) {
	s := loc_start(n)
	e := loc_end(n)
	assert s >= 0, 'loc.start must be >= 0'
	assert e > s, 'loc.end (${e}) must be > loc.start (${s})'
	assert e <= source.len, 'loc.end (${e}) must be <= source.len (${source.len})'
	// substring extraction must not panic.
	_ := source[s..e]
	if children := n['children'] {
		for c in children.as_array() {
			validate_loc_recursive(c.as_map(), source)
		}
	}
}

fn test_loc_invariants_complex_source() {
	source := "[doc [user :id 1 :name 'alice' [email 'a@x']] [other 'value']]"
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	validate_loc_recursive(n, source)
}

fn test_loc_substring_resolves_to_element_open() {
	source := '[outer [inner]]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	children := n['children']!.as_array()
	inner := children[0].as_map()
	// inner element's loc substring must start with `[inner`.
	s := loc_start(inner)
	e := loc_end(inner)
	assert source[s..e] == '[inner]'
}

// ── Round-trip / shape ─────────────────────────────────────────────────

fn test_round_trip_parses_as_valid_json() {
	source := "[user :id 1 :name 'alice' [profile :email 'a@x']]"
	out := cx.code_tree(source) or { panic('${err}') }
	// json2.raw_decode must accept the emitter's output without
	// raising.
	_ := json2.decode[json2.Any](out) or {
		panic('emitter produced invalid JSON: ${err.msg()}')
	}
}

fn test_required_fields_present_per_kind() {
	cases := {
		'[user]':           'element'
		'[user :id 1]':     'element'
		"[name 'a']":       'element'
		'[?for]':           'directive'
		'42':               'scalar'
		'/foo':             'path'
	}
	for src, expected_kind in cases {
		out := cx.code_tree(src) or { panic('${err} for ${src}') }
		n := get_obj(parse_json(out))
		assert kind_of(n) == expected_kind, 'expected ${expected_kind} for ${src}, got ${kind_of(n)}'
		// loc always present.
		assert 'loc' in n, 'missing loc for ${src}'
		// kind-specific required fields.
		match expected_kind {
			'element', 'directive' { assert 'name' in n }
			'scalar', 'path'       { assert 'value' in n }
			else {}
		}
	}
}

// ── Multiple top-level statements ──────────────────────────────────────

fn test_multiple_top_level_wraps_in_synthetic_root() {
	source := '[a][b]'
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	assert n['name']!.str() == 'root'
	children := n['children']!.as_array()
	assert children.len == 2
	c0 := children[0].as_map()
	c1 := children[1].as_map()
	assert c0['name']!.str() == 'a'
	assert c1['name']!.str() == 'b'
}

// ── Attribute value typing ─────────────────────────────────────────────

fn test_element_body_atom_value_sequence() {
	// Colon tokens are atom scalars (not typed attributes); each following
	// value is its own scalar/text node — eight per-token body items.
	source := "[x :i 42 :f 3.14 :b true :s 'hi']"
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	children := n['children']!.as_array()
	assert children.len == 8, 'expected 8 body items, got ${children.len}'
	assert children[0].as_map()['value']!.str() == ':i'
	assert children[1].as_map()['value']!.int() == 42
	assert children[2].as_map()['value']!.str() == ':f'
	assert children[3].as_map()['value']!.f64() == 3.14
	assert children[4].as_map()['value']!.str() == ':b'
	assert children[5].as_map()['value']!.bool() == true
	assert children[6].as_map()['value']!.str() == ':s'
	t := children[7].as_map()
	assert kind_of(t) == 'text'
	assert t['value']!.str() == 'hi'
}

// ── Edge cases ─────────────────────────────────────────────────────────

fn test_element_with_text_and_nested_element() {
	source := "[doc 'intro' [user]]"
	out := cx.code_tree(source) or { panic('${err}') }
	n := get_obj(parse_json(out))
	assert kind_of(n) == 'element'
	children := n['children']!.as_array()
	assert children.len == 2
	assert kind_of(children[0].as_map()) == 'text'
	assert kind_of(children[1].as_map()) == 'element'
}

fn test_deeply_nested_elements() {
	source := '[a [b [c [d [e]]]]]'
	out := cx.code_tree(source) or { panic('${err}') }
	mut cur := get_obj(parse_json(out)).clone()
	mut depth := 0
	for {
		depth++
		if children := cur['children'] {
			arr := children.as_array()
			if arr.len == 0 { break }
			cur = arr[0].as_map().clone()
		} else { break }
	}
	assert depth == 5
}

// ── The streamed-input fast path (§11.6 gate-15; stream 17 W5, L91 —
// the parser_streaming disposition). Parity is the contract: the fast
// path's bytes must equal the materializing path's, its ENGAGEMENT is
// witnessed by the commit counter (dead-seam guard), and every
// decline case falls back losslessly. ─────────────────────────────────

// streamed_vs_buffered runs one program down BOTH evaluation paths and
// returns (streamed, buffered) for the caller to compare.
//
// LIVENESS IS ENFORCED HERE, not left to callers (#851). A comparison of two
// results is only evidence if the results exist: two paths that both fail, or
// both produce nothing, agree perfectly and test nothing. Three such vacuous
// passes were found in one #804 test file in a single session, and the only
// reason they were caught is that someone deleted working code and noticed the
// test stayed green.
//
// Both guards below are cheap and neither has ever fired on the existing
// callers — verified by instrumenting this function and running the lane, which
// reported zero both-empty comparisons across every use. They exist so a future
// test cannot silently join that class.
//
// If you legitimately need to assert that BOTH paths produce nothing (a refusal
// that must emit no bytes on either side), do not weaken this — write the
// assertion in the test, where the intent is visible.
fn streamed_vs_buffered(input string, prog string) (string, string) {
	buffered := code.eval_code(input, prog, 'text') or { panic('buffered failed: ${err}') }
	mut collector := &StreamCollector{}
	sink := fn [mut collector] (chunk string) ! {
		collector.append(chunk)!
	}
	code.eval_code_streaming(input, prog, 'text', sink) or { panic('streaming failed: ${err}') }
	streamed := collector.chunks.join('')
	if streamed.len == 0 && buffered.len == 0 {
		panic('VACUOUS PARITY: both paths produced NO output for `${prog}`, so comparing them ' +
			'proves nothing (#851). Use a program that emits, or assert the emptiness ' +
			'explicitly in the test.')
	}
	return streamed, buffered
}

fn test_streamed_input_fast_path_engages_and_matches() {
	input := '[data [user [id 1] [name "a"]] [user [id 2] [name "b"]] [user [id 3] [name "c"]]]'
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() > before, 'the fast path must ENGAGE for the canonical shape (dead-seam guard)'
}

// ── #845 — the [?map] streamed-INPUT lane ────────────────────────────────
//
// `[?map]` streamed its OUTPUT but materialized the whole document for its
// SOURCE, which measured as a growing live set (gate-15 map shape decaying
// 2.0 -> 0.8 MB/s inside one process, failing the jitter clamp at 61.5%).
// These assert the lane both ENGAGES and produces the materializing path's
// bytes — the commits counter is the dead-seam guard, without which a parity
// test passes by never taking the fast path at all.

fn test_streamed_map_fast_path_engages_and_matches() {
	input := '[data [user [id 1] [name "a"]] [user [id 2] [name "b"]] [user [id 3] [name "c"]]]'
	prog := '[?map \$doc/user [using [?fn (\$u) \$u]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'map streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() > before,
		'the [?map] fast path must ENGAGE for the canonical shape (dead-seam guard)'
}

// The two-step form steps INTO each child, which forces a lazy record and pays
// the resolve the one-step form skips — a different code path, so it gets its
// own engage+parity assertion.
fn test_streamed_map_two_step_engages_and_matches() {
	input := '[data [row [user "a"]] [row [user "b"]] [row [user "c"]]]'
	prog := '[?map \$doc/row/user [using [?fn (\$u) \$u]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'two-step map streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() > before, 'the two-step map form must engage'
}

// REFUSAL PARITY (#845, the load-bearing property): the map lane reproduces the
// [?for] lane's deferred commit, so a walk ending with 0 or 1 matches DECLINES
// with nothing emitted and the materializing path answers. That is what keeps
// the ACCEPTED-INPUT SET from moving — the low-cardinality shapes
// (single-match node-set, field-read atomization, the #21 lone-collection
// unwrap) stay owned by one path instead of being re-derived on two.
//
// The commits assertion here is the INVERSE of the others: it must NOT rise.
fn test_streamed_map_low_cardinality_declines_to_materializing() {
	// exactly ONE match — under the deferred commit this never commits
	input := '[data [user [id 1] [name "a"]] [other [id 2]]]'
	prog := '[?map \$doc/user [using [?fn (\$u) \$u]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'single-match map streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() == before,
		'a single-match walk must DECLINE pre-emission, leaving the low-cardinality ' +
		'semantics to the materializing path: ${got}'
}

// [par] fans out over a bounded pool and reassembles by source index, which
// needs the item list up front. Streaming input into it is separate work, so
// the plan declines it — deliberately, not by omission.
fn test_streamed_map_par_declines_but_still_matches() {
	input := '[data [user [id 1]] [user [id 2]] [user [id 3]]]'
	prog := '[?map \$doc/user [using [?fn (\$u) \$u]] [par]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'par map streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() == before,
		'[par] must decline the streamed-input lane (it needs the item list up front)'
}

// A BLOCK body declines the map fast path, and this test exists because the
// first implementation of the lane got it WRONG in a way no parity test on a
// bare `[?map]` could see. A block's earlier siblings are evaluated for their
// effects (def / closure registration, mutations) only on the materializing
// path, so a fast path that ran first resolved `:using` against an environment
// the siblings had not populated: this program returned three
// `no callable "bump"` errs instead of three `[bumped …]`.
//
// Hoisting the sibling loop above the fast path would not be a fix either — a
// walk that then declined would leave the materializing path to re-run those
// effects, and a mutation is not idempotent. Declining the shape is the
// conservative direction.
fn test_streamed_map_block_body_declines_and_sees_its_siblings() {
	input := '[data [user [id 1]] [user [id 2]] [user [id 3]]]'
	prog := '[?def bump scope=public pure [returns element] (\$u::any) [bumped \$u]]\n' +
		'[?map \$doc/user [using [?fn (\$u) [\$bump \$u]]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'block-body map streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() == before,
		'a block body must DECLINE the map fast path (its siblings are evaluated later)'
	// The point of the case: the sibling def must actually have been reachable.
	assert got.contains('bumped'), 'the sibling [?def] was not registered: ${got}'
	assert !got.contains('no callable'), 'the sibling [?def] was not registered: ${got}'
}

// The shared program-text scans: a SECOND `$doc` spelling anywhere declines,
// because the fast path never binds the document and a second reference could
// read it. Same conservative rule as the [?for] lane, and now literally the
// same function.
fn test_streamed_map_second_doc_spelling_declines() {
	input := '[data [user [id 1]] [user [id 2]] [user [id 3]]]'
	prog := '[?map \$doc/user [using [?fn (\$u) [pair \$u [n [\$count \$doc/user]]]]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'second-spelling map streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() == before,
		'a second \$doc spelling must decline the fast path'
}

// #804 leg 6 — `$_position` is bound per surviving candidate, which costs a
// ScalarNode allocation plus a map insert on EVERY item. The streamed-input
// fast path now SKIPS it when the program text cannot mention it.
//
// This test exists because the lazy/strict differential CANNOT catch a bug
// here: both of its arms run the same fast path and would compute the same
// `needs_position`, so both would be wrong together and agree. The only
// instrument that sees it is streamed-vs-MATERIALIZING parity, which is what
// this is.
//
// Two directions, and both matter:
//   - a program that DOES read `$_position` must still get the right values
//     (the skip must not fire), and
//   - a program that does not must still produce the materializing path's
//     bytes (the skip must not change anything observable).
fn test_streamed_input_position_parity() {
	input := '[data [user [id 1]] [user [id 2]] [user [id 3]] [user [id 4]]]'

	// Reads $_position: the skip must NOT fire, and the numbers must be the
	// 1-based OUTPUT index, not the input index.
	prog_reads := '[?for [in \$u \$doc/user] [yield [p \$_position]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog_reads)
	assert got == want, '\$_position streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() > before,
		'the fast path must still ENGAGE when \$_position is read (else this asserts nothing)'
	assert got.contains('1') && got.contains('4'),
		'positions must actually be emitted, 1..4: ${got}'

	// Reads $_position AFTER a :drop, so output index and input index differ —
	// a skip-related bug that merely echoed the input counter would pass the
	// case above and fail this one.
	prog_dropped := '[?for [in \$u \$doc/user] [drop 2] [yield [p \$_position]]]'
	g2, w2 := streamed_vs_buffered(input, prog_dropped)
	assert g2 == w2, '\$_position after :drop streamed != buffered:\nstream: ${g2}\nbuffer: ${w2}'

	// Does NOT read $_position: the skip fires, and the bytes must be
	// unchanged from the materializing path.
	prog_plain := '[?for [in \$u \$doc/user] [yield \$u]]'
	g3, w3 := streamed_vs_buffered(input, prog_plain)
	assert g3 == w3, 'skipping \$_position changed observable output:\nstream: ${g3}\nbuffer: ${w3}'
}

// #804 leg 7 — the streamed-input walk's per-item frame takes its bindings map
// from the #36 per-thread frame pool instead of allocating a fresh one per
// record. The map is therefore REUSED across records.
//
// WHAT THE LAZY/STRICT DIFFERENTIAL CANNOT SEE, and this can. Both of that
// differential's arms run the same streamed walk and pool identically, so a
// pooling bug makes them wrong TOGETHER and they agree — the same blind spot
// leg 6 hit with `$_position`. The materializing path still clones a fresh
// frame per item, so streamed-vs-MATERIALIZING parity is the instrument with
// reach here.
//
// WHAT THIS COVERS AND WHAT IT DOES NOT, stated plainly because a differential
// whose reach is assumed is exactly how this issue collected three vacuous
// passes in one session. It covers CROSS-RECORD LEAKAGE: a name written while
// record N is in flight that record N+1 can still observe. It does NOT cover
// an escaped live alias of a frame — nothing in these programs outlives its
// own record, so nothing here could witness one. That case belongs to #36's
// `-d cx_frame_poison` build, where a returned map is cleared and never
// reused, so any surviving alias reads empty and breaks the suite on its
// missing bindings.
fn test_streamed_input_pooled_frame_parity() {
	input := '[data [user [id 1] [tag "a"]] [user [id 2] [tag "b"]] ' +
		'[user [id 3] [tag "c"]] [user [id 4] [tag "d"]]]'

	// A path read FORCES the lazy record and memoises by writing the forced
	// element back over the loop binding (#804 leg 4) — a write straight into
	// the pooled map, on every record.
	prog_path := '[?for [in \$u \$doc/user] [yield [n \$u/id]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog_path)
	assert got == want, 'pooled-frame path read streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() > before,
		'the fast path must ENGAGE, else this test asserts nothing about pooling'
	assert got.contains('1') && got.contains('4'), 'every record must be read: ${got}'

	// A `[= …]` clause binds a SECOND name per record and derives its own child
	// frame from the pooled one.
	prog_let := '[?for [in \$u \$doc/user] [= \$t \$u/tag] [yield [n \$t]]]'
	g2, w2 := streamed_vs_buffered(input, prog_let)
	assert g2 == w2, 'pooled-frame [= ] clause streamed != buffered:\nstream: ${g2}\nbuffer: ${w2}'
	assert g2.contains('a') && g2.contains('d'), 'every record must bind: ${g2}'

	// Two names live at once, both read in the yield body: a record that
	// inherited a stale binding for either would answer with the WRONG PAIR
	// while still producing perfectly well-formed output.
	prog_pair := '[?for [in \$u \$doc/user] [= \$t \$u/tag] [yield [n \$u/id \$t]]]'
	g3, w3 := streamed_vs_buffered(input, prog_pair)
	assert g3 == w3, 'pooled-frame two-name streamed != buffered:\nstream: ${g3}\nbuffer: ${w3}'

	// A lambda created per record CAPTURES the loop binding. If that capture
	// aliased the pooled map rather than snapshotting it (eval_fn ->
	// snapshot_bindings), the applied result would follow the map's reuse.
	prog_fn := '[?for [in \$u \$doc/user] [= \$f [?fn \$x [n \$x \$u/id]]] [yield [\$f \$u/tag]]]'
	g4, w4 := streamed_vs_buffered(input, prog_fn)
	assert g4 == w4, 'pooled-frame lambda capture streamed != buffered:\nstream: ${g4}\nbuffer: ${w4}'

	// After a [drop], so the surviving records are not the leading ones. A
	// pooling bug that happened to line up with input order would pass every
	// case above and fail this one.
	prog_drop := '[?for [in \$u \$doc/user] [drop 2] [= \$t \$u/tag] [yield [n \$u/id \$t]]]'
	g5, w5 := streamed_vs_buffered(input, prog_drop)
	assert g5 == w5, 'pooled-frame after [drop] streamed != buffered:\nstream: ${g5}\nbuffer: ${w5}'
}

fn test_streamed_input_two_step_with_take() {
	input := '[data [users [user [id 1]] [user [id 2]] [user [id 3]] [user [id 4]]] [other 1]]'
	prog := '[?for [in \$u \$doc/users/user] [take 2] [yield \$u]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'two-step streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() > before, 'the two-step form must engage'
}

fn test_streamed_input_single_match_falls_back() {
	// ONE match: the materializing path owns the single-match
	// field-read shape (and the #21 lone-collection unwrap) — the fast
	// path must decline WITHOUT emitting and the answers must agree.
	input := '[data [user [id 1] [name "only"]] [meta [src "x"]]]'
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'single-match streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
	assert code.streamed_input_commits() == before, 'single-match must NOT commit (deferred-commit fallback)'
}

fn test_streamed_input_zero_match_falls_back() {
	input := '[data [meta [src "x"]] [meta [src "y"]]]'
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	before := code.streamed_input_commits()
	// A zero-match walk emits nothing on BOTH paths, so it cannot use
	// streamed_vs_buffered: comparing "" to "" is the vacuous shape #851 is
	// about. The emptiness is asserted DIRECTLY here, where the intent is
	// visible, and the load-bearing assertion is the one below it — the fast
	// path must decline rather than commit.
	buffered := code.eval_code(input, prog, 'text') or {
		assert false, 'buffered failed: ${err}'
		return
	}
	mut collector := &StreamCollector{}
	sink := fn [mut collector] (chunk string) ! {
		collector.append(chunk)!
	}
	code.eval_code_streaming(input, prog, 'text', sink) or {
		assert false, 'streaming failed: ${err}'
		return
	}
	streamed := collector.chunks.join('')
	assert buffered == '', 'a zero-match comprehension must emit nothing (buffered): `${buffered}`'
	assert streamed == '', 'a zero-match comprehension must emit nothing (streamed): `${streamed}`'
	assert code.streamed_input_commits() == before, 'zero-match must NOT commit'
}

fn test_streamed_input_doc_reference_elsewhere_falls_back() {
	// `$doc` appears beyond the source → the conservative source scan
	// declines; output parity holds through the materializing path.
	input := '[data [user [id 1]] [user [id 2]]]'
	prog := '[?for [in \$u \$doc/user] [yield [pair \$u \$doc/user]]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'extra-\$doc-reference streamed != buffered'
	assert code.streamed_input_commits() == before, 'a second \$doc reference must decline the fast path'
}

fn test_streamed_input_anchor_input_falls_back() {
	// `&` rides resolve_ids (document-global) — the byte gate declines.
	input := '[data [user &u1 [id 1]] [user [id 2]] [link &u1]]'
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	before := code.streamed_input_commits()
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'anchor-bearing streamed != buffered'
	assert code.streamed_input_commits() == before, 'anchors must decline the fast path'
}

fn test_streamed_input_multidoc_refuses_both_paths() {
	// A `---` tail: cx.parse refuses multi-doc input outright ("use
	// parse_stream"), so BOTH paths must refuse it.
	//
	// #804 leg 3 (ruled 1a) changed WHEN the streamed arm discovers this,
	// and this test now pins the new contract rather than the old one. The
	// separate validation pass used to see the bad tail before anything was
	// emitted, so the fast path declined and the materializing fallback
	// produced the refusal. It was removed because it cost a whole
	// traversal: the two-pass ceiling measured 201.7 MB/s against §11.4.4's
	// 200 floor, so a perfect evaluation pass still could not pass the gate.
	//
	// What MUST still hold, and is the invariant worth having a test for:
	// the input is still REFUSED. The accepted-input set did not move — only
	// the moment a late refusal is found, and what has been written by then.
	input := '[data [user [id 1]] [user [id 2]]]\n---\n[data [user [id 9]]]\n'
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	before := code.streamed_input_commits()
	if _ := code.eval_code(input, prog, 'text') {
		assert false, 'buffered must refuse multi-doc input'
	}
	mut collector := &StreamCollector{}
	sink := fn [mut collector] (chunk string) ! {
		collector.append(chunk)!
	}
	if _ := code.eval_code_streaming(input, prog, 'text', sink) {
		assert false, 'streaming must refuse multi-doc input'
	}
	// The fast path now COMMITS before reaching the bad tail — that is the
	// ruled trade, asserted positively so it cannot be reverted silently.
	assert code.streamed_input_commits() > before,
		'leg 3 removed the pre-emission validation pass, so a late-tail input now commits'
	// The sink saw nothing here, but do NOT read that as a guarantee: this
	// input is far below StreamCtx's 64 KiB flush threshold, so the emitted
	// records were still buffered when the error arrived. On an input large
	// enough to flush, bytes DO precede the error — see
	// test_streamed_input_late_error_may_emit_first, which is the honest
	// statement of what leg 3 cost.
	assert collector.chunks.join('') == '',
		'below the flush threshold nothing should have reached the sink yet'
}

// The cost of leg 3, made visible. A late input error on an input large
// enough to cross the flush threshold produces OUTPUT FOLLOWED BY AN ERROR,
// where the two-pass engine produced a clean refusal and nothing else.
//
// This test exists because the small-input case above cannot show it — the
// records are still in StreamCtx's buffer when the error arrives, so the
// trade looks free there and is not. A change that is paid for should have a
// test that names the price.
fn test_streamed_input_late_error_may_emit_first() {
	// ~2000 records puts the streamed output well past the 64 KiB flush
	// threshold before the malformed tail is reached.
	mut parts := []string{cap: 2100}
	parts << '[data\n'
	for i in 0 .. 2000 {
		parts << '  [user :id ${i} :name "n-${i}"]\n'
	}
	parts << ']\n---\n[data [user :id 9 :name "x"]]\n'
	input := parts.join('')
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'

	// The materializing path refuses cleanly, as it always did.
	if _ := code.eval_code(input, prog, 'text') {
		assert false, 'buffered must refuse multi-doc input'
	}

	mut collector := &StreamCollector{}
	sink := fn [mut collector] (chunk string) ! {
		collector.append(chunk)!
	}
	if _ := code.eval_code_streaming(input, prog, 'text', sink) {
		assert false, 'streaming must STILL refuse multi-doc input — the accepted-input set did not move'
	}
	got := collector.chunks.join('')
	assert got.len > 0,
		'leg 3: a late input error now arrives AFTER output has streamed; this test documents that cost'
	assert got.contains('[user'),
		'and what streamed is real records, not a fragment: ${got#[..80]}'
}

// ── #853 — a [?quote] HOLE's err propagates; a literal [err] stays data ────
//
// code.md §6.4.3.1 is explicit: "holes are evaluated once, left-to-right, at
// quote-eval time; a hole's `[err]` propagates railway-style (§9.2) then." It
// did not. The lift resolved each hole, got the err, and appended it to the
// tree like any other child — so a refusal ended up buried in a document,
// unmatchable by `[?match … [case [err …] …]]` because by then it was a node.
// #853 caught it as a 200 OK with `<err code="…">` serialized into a page.
//
// It also broke §6.4.3's stated equivalence ("building with [?quote]+holes and
// building imperatively with [?element]/[?attr]/[?entry] produce the SAME
// tree"): the imperative path already aborted on a hole err, only quote did
// not. So both spellings are asserted here, and they must agree.
//
// THE DISCRIMINATOR IS THE POSITION, NOT THE VALUE, and that is why the third
// case is in this test. A literal `[err …]` written inside a quoted form is
// DATA and must survive — a fix that keyed off "is this value an err" would
// pass the first two assertions and silently make err-shaped documents
// inexpressible. Same for a plain positional child, which stays CONTAINED by
// the deliberate choice recorded in eval_dc_body_items ("element construction
// is data-building, not a railway").
fn test_quote_hole_err_propagates_but_literal_err_stays_data() {
	// 1. an [?unquote] hole whose expression refuses
	got1 := code.eval_code('', '[?quote [foo [?unquote [\$concat (1) "-x"]]]]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert got1.trim_space().starts_with('[err '),
		'#853: an [?unquote] hole err must BE the result, not a child — got ${got1}'

	// 2. a [?splice] hole whose expression refuses
	got2 := code.eval_code('', '[?quote [foo [?splice [\$concat (1) "-x"]]]]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert got2.trim_space().starts_with('[err '),
		'#853: a [?splice] hole err must BE the result, not a child — got ${got2}'

	// 3. §6.4.3 equivalence: the imperative spelling agrees with the quoted one
	got3 := code.eval_code('', '[foo [?attr "v" [\$concat (1) "-x"]]]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert got3.trim_space().starts_with('[err '),
		'the imperative construction hole must agree with the quoted one — got ${got3}'

	// 4. a LITERAL [err …] inside a quoted form is DATA and must survive
	got4 := code.eval_code('', '[?quote [foo [err code=cx-err:CXER9999]]]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert got4.trim_space().starts_with('[foo '),
		'a literal [err] in a quoted form is data, not a refusal — got ${got4}'
	assert got4.contains('CXER9999'), 'the literal err lost its content — got ${got4}'

	// 5. a hole that succeeds still grafts normally
	got5 := code.eval_code('', '[?quote [foo [?unquote "ok"] "b"]]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert got5.contains('ok'), 'a successful hole must still graft — got ${got5}'
	assert !got5.contains('[err '), 'a successful hole must not refuse — got ${got5}'
}

// ── #848 — a wrapped err reports its MESSAGE, and err_summary stays code-only ─
//
// Every err-wrapping surface formatted through `err_summary`, which returns
// the CODE alone. So `[$io:read-file F]!` told the user `cx-err:CXER3401` and
// not `E_IO_NOT_FOUND: read-file thing.feature.cxd` — the filename, the one
// fact that makes the failure actionable, was exactly what got dropped.
//
// It mattered more than a cosmetic defect because `!` is the operator §6.2
// PRESCRIBES for guarding a fallible binding ("guard the BINDING, not the
// query"): an unguarded read gave a wrong answer with no message, and a
// guarded one gave a right refusal with no message either.
//
// BOTH functions are asserted here, and the second assertion is the point.
// `pipe_tap_propagates` DISPATCHES on `err_summary` (§8.9.2 propagates a tap's
// err iff its code is CXER0001 or CXER0260), so appending a message to that
// function would have silently broken tap flow control. The fix is a separate
// display accessor, and this test is what stops the two being merged later.
fn test_err_diagnostic_carries_the_message_and_summary_stays_code_only() {
	e := cx.Node(cx.Element{
		name:  'err'
		attrs: [
			cx.Attribute{
				name:  'code'
				value: cx.ScalarValue('cx-err:CXER3401')
			},
			cx.Attribute{
				name:  'message'
				value: cx.ScalarValue('E_IO_NOT_FOUND: read-file thing.feature.cxd')
			},
		]
	})

	diag := code.err_diagnostic(e)
	assert diag.contains('cx-err:CXER3401'), '#848: the code must survive — got ${diag}'
	assert diag.contains('E_IO_NOT_FOUND'), '#848: the symbolic name must survive — got ${diag}'
	assert diag.contains('thing.feature.cxd'),
		'#848: the FILENAME is the actionable fact and must survive — got ${diag}'

	// err_summary is the flow-control accessor and must NOT gain the message.
	summ := code.err_summary(e)
	assert summ == 'cx-err:CXER3401',
		'err_summary must stay code-only — pipe_tap_propagates dispatches on it (got ${summ})'

	// A code-only err (no message) degrades to the code, not to `code: `.
	bare := cx.Node(cx.Element{
		name:  'err'
		attrs: [cx.Attribute{
			name:  'code'
			value: cx.ScalarValue('cx-err:CXER0001')
		}]
	})
	assert code.err_diagnostic(bare) == 'cx-err:CXER0001',
		'a message-less err must render as the bare code — got ${code.err_diagnostic(bare)}'
}

// ── #858 — a construction hole proves the body is an element body ──────────
//
// With `[?def categories …]` in scope, `[categories [?splice …]]` was
// evaluated as a CALL to the def, so the splice landed in an argument slot and
// the program failed with "[?splice …] is valid only in a multi-sibling slot"
// — a true statement naming the wrong thing, because the body was a body until
// the call arm took it. Renaming either side made it work, so the capture
// acted at a distance.
//
// Cause: `all_items_are_expr_position` inspected `ProgramLiteral` nodes only,
// and a hole is a `ProgramDirective`, so it fell straight through the gate.
// `[?splice]`/`[?attr]`/`[?entry]` are valid ONLY where a body / multi-sibling
// slot / map-entry list is admitted (§6.4.2, §6.4.3), so their presence proves
// construction — exactly as a bareword data child already did.
//
// THE LAST TWO ASSERTIONS ARE THE LOAD-BEARING ONES. Bare-head-as-call is
// deliberate (#55) and nested-def-call-in-argument-position is deliberate
// (#59); the obvious "stop defs capturing bare heads" fix would break both.
// This test is what says the narrow fix did not.
fn test_construction_hole_keeps_an_element_body_from_becoming_a_call() {
	// The reported shape: a def named like the container element.
	got := code.eval_code('', '[?def categories pure [returns any] () ([cat], [cat])]' +
		'[?let [= \$doc [categories [?splice [?for [in \$c ([a], [b])] [yield [category]]]]]]' +
		' [\$cx:canonical \$doc]]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert got.contains('[categories'),
		'#858: the element body must construct, not dispatch to the def — got ${got}'
	assert got.contains('[category]'), '#858: the splice must graft its siblings — got ${got}'
	assert !got.contains('multi-sibling'),
		'#858: the splice must not be treated as a call argument — got ${got}'

	// #55 — a bare head that names a def with a ZERO-item body still CALLS.
	call0 := code.eval_code('', '[?def f () "hi"] [f]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert call0.contains('hi'), '#55 regression: [f] must call the def, not construct [f] — got ${call0}'

	// #59 — a nested def call in ARGUMENT position still applies.
	nested := code.eval_code('', '[?def f (\$x) [\$concat \$x "!"]] [?def g (\$y) \$y] [g [f "a"]]',
		'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert nested.contains('a!'),
		'#59 regression: [g [f "a"]] must apply both, not construct data — got ${nested}'
}

// ── #804 leg 11 — the lazy name compare must REJECT a non-matching sibling ──
//
// A lazy record used to carry a `name string` built at construction (one heap
// string per record) for a name with exactly one reader: the streamed walk's
// `child_name != step1.name` compare. It now carries the name's OFFSETS and
// `name_eq` compares bytes against the buffer it already holds.
//
// THIS TEST EXISTS BECAUSE THE LAZY/STRICT DIFFERENTIAL IS BLIND TO IT. I broke
// `name_eq` on purpose — made it admit a length mismatch — and
// lazy_record_differential_test stayed fully GREEN, because its corpus gives
// every child the same name, so a length mismatch never arises and a
// too-permissive compare selects nothing extra.
//
// The compare is the record SELECTOR: too permissive and the walk yields
// siblings the program did not ask for, which is a wrong ANSWER on
// well-formed input rather than a crash. So the corpus here deliberately
// INTERLEAVES names of different lengths, and asserts both directions —
// the selected ones arrive and the others do not.
fn test_streamed_lazy_name_compare_rejects_other_siblings() {
	// Interleaved siblings whose names differ from `user` in LENGTH and in
	// CONTENT, so both halves of name_eq are exercised.
	mut parts := []string{}
	parts << '[data\n'
	for i in 0 .. 40 {
		parts << '  [user :id ${i} :name "u${i}"]\n'
		parts << '  [other :id ${i} :name "o${i}"]\n'
		parts << '  [usr :id ${i} :name "s${i}"]\n'
		parts << '  [username :id ${i} :name "n${i}"]\n'
		// SAME LENGTH as `user`, different bytes — without this the length
		// check alone satisfies the test and the byte loop is never exercised.
		// Found by breaking the loop and watching the test stay green.
		parts << '  [oser :id ${i} :name "z${i}"]\n'
		parts << '  [usek :id ${i} :name "k${i}"]\n'
	}
	parts << ']\n'
	input := parts.join('')
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'

	one_shot := code.eval_code(input, prog, 'text') or {
		assert false, 'one-shot failed: ${err}'
		return
	}
	mut collector := &StreamCollector{}
	sink := fn [mut collector] (chunk string) ! {
		collector.append(chunk)!
	}
	code.eval_code_streaming(input, prog, 'text', sink) or {
		assert false, 'streaming failed: ${err}'
		return
	}
	got := collector.chunks.join('')

	// Streamed output must equal the materializing path byte for byte.
	assert got == one_shot,
		'leg 11: the streamed name compare disagrees with the materializing walk'

	// And it must be the RIGHT set, asserted directly rather than only by
	// agreement — both paths could be wrong together.
	assert got.contains('[user '), 'the selected siblings must be present: ${got#[..80]}'
	assert !got.contains('[other'),
		'leg 11: a same-prefix-different-length sibling was selected — name_eq is too permissive'
	assert !got.contains('[usr'),
		'leg 11: a shorter sibling was selected — name_eq is too permissive'
	assert !got.contains('[username'),
		'leg 11: a longer sibling sharing the whole prefix was selected — name_eq is too permissive'
	assert !got.contains('[oser'),
		'leg 11: a SAME-LENGTH sibling differing in the first byte was selected — the byte loop is not running'
	assert !got.contains('[usek'),
		'leg 11: a SAME-LENGTH sibling differing in the LAST byte was selected — the byte loop stops short'
}

fn test_streamed_input_reserved_ns_violation_errors_both_paths() {
	// A child rebinding the reserved `cx` prefix: the per-child
	// resolution runs the SAME validate_reserved_ns_bindings the
	// materializing parse runs — both paths must refuse.
	input := '[data [user [id 1]] [user [id 2]] [user xmlns:cx="http://example.org/evil" [id 3]]]'
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	if _ := code.eval_code(input, prog, 'text') {
		assert false, 'buffered must refuse the reserved-ns rebind'
	}
	mut collector := &StreamCollector{}
	sink := fn [mut collector] (chunk string) ! {
		collector.append(chunk)!
	}
	if _ := code.eval_code_streaming(input, prog, 'text', sink) {
		assert false, 'streaming must refuse the reserved-ns rebind'
	}
	// The validation pre-pass declines BEFORE any output — the refusal
	// is clean on both paths, never partial-output-then-error.
	assert collector.chunks.join('') == '', 'the refusal must precede any streamed output'
}

fn test_streamed_input_namespace_doc_parity() {
	// Root-declared namespace with prefixed children: per-child
	// resolution under the root context must render identically to the
	// whole-document resolve.
	input := '[data xmlns:m="http://example.org/m" [m:user [id 1]] [m:user [id 2]]]'
	prog := '[?for [in \$u \$doc/m:user] [yield \$u]]'
	got, want := streamed_vs_buffered(input, prog)
	assert got == want, 'namespaced streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
}

// ── #806 refusal-IDENTITY parity (I5 audit AF-1; stream 17 W7). The
// W5 criterion, pinned as fixtures: an input the materializing path
// refuses ALWAYS declines pre-emission and the fallback reproduces the
// EXACT refusal — same message, compared, not just 'both refuse'. ────

// refusal_identity_pair runs BOTH paths on a refused input and returns
// (buffered_refusal, streamed_refusal, streamed_output_bytes).
fn refusal_identity_pair(input string, prog string) (string, string, string) {
	mut buffered_msg := ''
	if _ := code.eval_code(input, prog, 'text') {
		assert false, 'buffered path must refuse this input'
	} else {
		buffered_msg = err.msg()
	}
	mut collector := &StreamCollector{}
	sink := fn [mut collector] (chunk string) ! {
		collector.append(chunk)!
	}
	mut streamed_msg := ''
	if _ := code.eval_code_streaming(input, prog, 'text', sink) {
		assert false, 'streaming path must refuse this input'
	} else {
		streamed_msg = err.msg()
	}
	return buffered_msg, streamed_msg, collector.chunks.join('')
}

fn test_streamed_input_at_reference_refusal_identity() {
	// #806 (1): `@name` references ride resolve_ids (document-global —
	// cannot run per child). The byte gate must decline them so the
	// fallback surfaces the materializing path's exact refusal; attr
	// position and body [ref @name] position both.
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	inputs := [
		'[data [user x=@nosuch [id 1]] [user [id 2]]]',
		'[data [user [id 1] [ref @nosuch]] [user [id 2]]]',
	]
	for input in inputs {
		before := code.streamed_input_commits()
		buffered, streamed, out := refusal_identity_pair(input, prog)
		assert streamed == buffered, 'refusal identity broken for `@` input:\nstream: ${streamed}\nbuffer: ${buffered}'
		assert out == '', 'the refusal must precede any streamed output'
		assert code.streamed_input_commits() == before, '`@` references must decline the fast path'
	}
}

fn test_streamed_input_unicode_id_refusal_identity() {
	// #806 (2): parser names are full Unicode ([L10a]) — the `#id`
	// byte gate must use the same predicate. Two `#émile` declarations
	// are a duplicate-ID refusal (CXER0208) on the materializing path;
	// the streamed path must reproduce it identically.
	input := '[data [user #émile [id 1]] [user #émile [id 2]]]'
	prog := '[?for [in \$u \$doc/user] [yield \$u]]'
	before := code.streamed_input_commits()
	buffered, streamed, out := refusal_identity_pair(input, prog)
	assert streamed == buffered, 'refusal identity broken for Unicode `#id`:\nstream: ${streamed}\nbuffer: ${buffered}'
	assert out == '', 'the refusal must precede any streamed output'
	assert code.streamed_input_commits() == before, 'Unicode `#id` candidates must decline the fast path'
}

fn test_streamed_input_rooted_yield_body_declines() {
	// #806 (3): a rooted path in the yield body needs $doc — the fast
	// path never binds it. The plan scan must decline rooted forms so
	// the materializing path answers (SUCCESS here), never
	// commit-then-CXER0001 past the fallback point.
	input := '[data [user [id 1]] [user [id 2]] [meta [src "x"]]]'
	for body_path in ['/meta', '//src'] {
		prog := '[?for [in \$u \$doc/user] [yield [pair \$u ${body_path}]]]'
		before := code.streamed_input_commits()
		got, want := streamed_vs_buffered(input, prog)
		assert got == want, 'rooted `${body_path}` streamed != buffered:\nstream: ${got}\nbuffer: ${want}'
		assert code.streamed_input_commits() == before, 'rooted `${body_path}` in the yield body must decline the fast path'
	}
}

// ── [131b] kind tests reach the PROGRAM parser (issue-809) ──────────────────
//
// POST-APPLY umbrella addition — not in
// scripts/consolidation/code_units.files; reconcile it into the manifest
// inputs before any future regeneration.
//
// The DATA-side reader (cx.parse_path) has admitted the four kind tests
// since the path reader landed — parser_units_umbrella_test.v pins it.
// The PROGRAM-side reader did not, so the grammar advertised surface no
// program could write: in expression position `$t/node()` misparsed as
// the path `$t/node` plus an empty sequence literal (observed as
// "expected 1 argument(s), got 2"), and in binding position it was a
// hard parse error. These cases pin the parse; the evaluation semantics
// are fixtured in conformance/code.cxd (program-cxpath-kindtest-*).

fn kind_test_of_first_step(src string) cx.ProgramPathKindTest {
	prog := cx.parse_program(src) or { panic('parse failed for `${src}`: ${err}') }
	body := prog.body
	if body is cx.ProgramPathExpr {
		return body.steps[0].kind_test
	}
	if body is cx.ProgramBinding {
		return body.path[0].kind_test
	}
	panic('`${src}` did not parse as a path or binding (got ${body.type_name()})')
}

fn test_program_parser_admits_rooted_kind_tests() {
	assert kind_test_of_first_step('//node()') == .any_node
	assert kind_test_of_first_step('//text()') == .text
	assert kind_test_of_first_step('//element()') == .element
	assert kind_test_of_first_step('//attribute()') == .attribute
}

fn test_program_parser_admits_binding_kind_tests() {
	assert kind_test_of_first_step('\$t/node()') == .any_node
	assert kind_test_of_first_step('\$t//text()') == .text
}

fn test_program_parser_kind_test_carries_no_name() {
	// One carrier: the enum. `name` stays empty exactly as ast-bin.md's
	// node-test discriminator table records it (payload "" for 0x04..0x07),
	// so the spelling can never drift from the test.
	prog := cx.parse_program('//text()') or { panic(err) }
	body := prog.body
	assert body is cx.ProgramPathExpr
	step := (body as cx.ProgramPathExpr).steps[0]
	assert step.name == '', 'a kind-test step must not also carry a name'
	assert step.ns_kind == .none
	assert step.ns_prefix == ''
}

fn test_program_parser_kind_test_takes_predicates() {
	prog := cx.parse_program('//text()[1]') or { panic(err) }
	step := (prog.body as cx.ProgramPathExpr).steps[0]
	assert step.kind_test == .text
	assert step.predicates.len == 1
}

fn test_program_parser_kind_test_under_explicit_axis() {
	prog := cx.parse_program('//user/attribute::attribute()') or { panic(err) }
	steps := (prog.body as cx.ProgramPathExpr).steps
	assert steps.len == 2
	assert steps[1].axis == .attribute
	assert steps[1].axis_explicit
	assert steps[1].kind_test == .attribute
}

fn test_program_parser_refuses_unknown_kind_test() {
	// Was a SILENT misparse (path + empty sequence literal). Both readers
	// now admit exactly the closed set of four.
	if _ := cx.parse_program('//bogus()') {
		assert false, '`//bogus()` must not parse'
	} else {
		assert err.msg().contains('unknown kind-test'),
			'expected an unknown-kind-test refusal, got: ${err}'
	}
}

fn test_program_parser_paren_group_after_step_is_still_an_operand() {
	// The kind-test rule keys on the EMPTY `()` pair. A non-empty paren
	// group after a path step stays what it was — a separate sequence
	// operand — so the retired paren-call surface ([132]-[134]) is not
	// resurrected by accident.
	prog := cx.parse_program('[\$count //admin (1, 2)]') or {
		panic('space-separated paren group must still parse: ${err}')
	}
	assert prog.body is cx.ProgramCall
	assert (prog.body as cx.ProgramCall).args.len == 2
}

fn test_program_parser_kind_test_round_trips_through_emit() {
	// canonical.md §2.12.4 — parens survive; and the emitted source is
	// what the dispatcher bridges REPARSE, so this is a data-loss guard.
	for src in ['//node()', '//text()[1]', '//user/attribute::attribute()',
	            '\$t/node()', '\$t//text()'] {
		prog := cx.parse_program(src) or {
			panic('parse failed for `${src}`: ${err}')
		}
		out := code.program_node_to_source(prog.body)
		assert out == src, 'kind-test round trip lost the spelling: `${src}` -> `${out}`'
	}
}
